    const data = img.data;
    for (let i = 3; i < data.length; i += 4) data[i] = 0; // transparent bg for putImageData blend

    for (const item of tris) {
      const albedo = FACE_COLORS[item.fi];
      const n = item.n;
      const scr = [];
      const cols = [];
      let ok = true;
      for (const vi of item.tri) {
        const wp = worldVerts[vi];
        const sp = project(wp);
        if (!sp) { ok = false; break; }
        scr.push(sp);
        cols.push(shadeVertex(wp, n, lightPos, albedo));
