    // putImageData overwrites, so redraw background behind transparent pixels:
    // cheaper: composite over background using a temp — instead, draw bg first into img.
  } else {
    // Wireframe path: draw projected edges.
    ctx.lineWidth = Math.max(1, DPR);
    ctx.strokeStyle = 'rgba(140, 220, 255, 0.9)';
    const proj = worldVerts.map(project);
    for (const q of QUADS) {
      const pts = q.map((i) => proj[i]);
      if (pts.some((p) => !p)) continue;
      ctx.beginPath();
      ctx.moveTo(pts[0][0], pts[0][1]);
      for (let i = 1; i < 4; i++) ctx.lineTo(pts[i][0], pts[i][1]);
      ctx.closePath();
      ctx.stroke();
    }
    // Highlight facing edges brighter.
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.35)';
    for (let fi = 0; fi < QUADS.length; fi++) {
      const q = QUADS[fi];
      const center = [0, 1, 2].reduce((acc, k) => acc, 0) && null;
      const c = [
        (worldVerts[q[0]][0] + worldVerts[q[2]][0]) / 2,
        (worldVerts[q[0]][1] + worldVerts[q[2]][1]) / 2,
        (worldVerts[q[0]][2] + worldVerts[q[2]][2]) / 2
      ];
      const toCam = norm(sub([0, 0, CAM_DIST], c));
      if (dot(worldNormals[fi], toCam) <= 0) continue;
      const pts = q.map((i) => proj[i]);
      if (pts.some((p) => !p)) continue;
      ctx.beginPath();
      ctx.moveTo(pts[0][0], pts[0][1]);
      for (let i = 1; i < 4; i++) ctx.lineTo(pts[i][0], pts[i][1]);
      ctx.closePath();
      ctx.stroke();
    }
  }

  // Light indicator (projected).
  const lp = project(lightPos);
  if (lp) {
    const grad = ctx.createRadialGradient(lp[0], lp[1], 0, lp[0], lp[1], 26 * DPR);
    grad.addColorStop(0, 'rgba(255, 244, 200, 0.95)');
    grad.addColorStop(1, 'rgba(255, 244, 200, 0)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(lp[0], lp[1], 26 * DPR, 0, Math.PI * 2);
    ctx.fill();
  }
}
